CREATE OR REPLACE FUNCTION ting_private.advance_order_status(p_order_id uuid, p_next_status text)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_order public.orders%ROWTYPE;
  updated_order public.orders%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING errcode = '42501';
  END IF;

  SELECT * INTO current_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND OR NOT ting_private.can_manage_tenant(current_order.tenant_id) THEN
    RAISE EXCEPTION 'order unavailable' USING errcode = '42501';
  END IF;

  IF NOT (
    (current_order.status = 'submitted' AND p_next_status = 'accepted') OR
    (current_order.status = 'accepted' AND p_next_status = 'preparing') OR
    (current_order.status = 'preparing' AND p_next_status = 'ready') OR
    (current_order.status = 'ready' AND p_next_status = 'completed')
  ) THEN
    RAISE EXCEPTION 'invalid order status transition' USING errcode = '23514';
  END IF;

  UPDATE public.orders
  SET
    status = p_next_status,
    accepted_at = CASE WHEN p_next_status = 'accepted' THEN now() ELSE accepted_at END,
    preparing_at = CASE WHEN p_next_status = 'preparing' THEN now() ELSE preparing_at END,
    ready_at = CASE WHEN p_next_status = 'ready' THEN now() ELSE ready_at END,
    completed_at = CASE WHEN p_next_status = 'completed' THEN now() ELSE completed_at END,
    updated_at = now()
  WHERE id = current_order.id
  RETURNING * INTO updated_order;

  RETURN updated_order;
END;
$function$;

ALTER FUNCTION "ting_private"."advance_order_status"(p_order_id uuid, p_next_status text) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION ting_private.assign_service_ticket_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
  routed_client_slug text;
BEGIN
  IF tg_table_schema <> 'public'
     OR tg_table_name <> 'service_tickets'
     OR tg_when <> 'BEFORE'
     OR tg_level <> 'ROW'
     OR tg_op NOT IN ('INSERT', 'UPDATE') THEN
    RAISE EXCEPTION 'assign_service_ticket_tenant may only run as the approved public.service_tickets row trigger'
      USING errcode = '42501';
  END IF;

  IF tg_op = 'UPDATE' THEN
    IF new.id IS DISTINCT FROM old.id
       OR new.tenant_id IS DISTINCT FROM old.tenant_id
       OR new.client_slug IS DISTINCT FROM old.client_slug
       OR new.table_number IS DISTINCT FROM old.table_number
       OR new.request_type IS DISTINCT FROM old.request_type
       OR new.created_at IS DISTINCT FROM old.created_at THEN
      RAISE EXCEPTION 'service ticket request details and ownership are immutable'
        USING errcode = '23514';
    END IF;
    RETURN new;
  END IF;

  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL THEN
    RAISE EXCEPTION 'service ticket insert requires a valid tenant route'
      USING errcode = '23514';
  END IF;

  SELECT tenant.client_slug
    INTO routed_client_slug
    FROM public.tenants tenant
   WHERE tenant.id = routed_tenant_id;

  IF new.tenant_id IS NOT NULL AND new.tenant_id <> routed_tenant_id THEN
    RAISE EXCEPTION 'tenant_id does not match the request route'
      USING errcode = '23514';
  END IF;
  IF new.client_slug IS NOT NULL AND new.client_slug <> routed_client_slug THEN
    RAISE EXCEPTION 'client_slug does not match the request route'
      USING errcode = '23514';
  END IF;

  new.tenant_id := routed_tenant_id;
  new.client_slug := routed_client_slug;
  RETURN new;
END;
$function$;

ALTER FUNCTION "ting_private"."assign_service_ticket_tenant"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION ting_private.assign_tenant_id_from_client_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    resolved_tenant_id UUID;
BEGIN
    IF TG_OP <> 'INSERT'
       OR TG_TABLE_SCHEMA <> 'public'
       OR TG_TABLE_NAME NOT IN ('menu_items', 'menu_events') THEN
        RAISE EXCEPTION
            'assign_tenant_id_from_client_slug may only run for approved INSERT triggers';
    END IF;

    IF NEW.client_slug IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT tenant.id
    INTO resolved_tenant_id
    FROM public.tenants AS tenant
    WHERE tenant.client_slug = NEW.client_slug;

    IF NEW.tenant_id IS NULL THEN
        NEW.tenant_id := resolved_tenant_id;

    ELSIF resolved_tenant_id IS NULL
          OR NEW.tenant_id <> resolved_tenant_id THEN
        RAISE EXCEPTION
            'tenant_id does not match client_slug'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$;

ALTER FUNCTION "ting_private"."assign_tenant_id_from_client_slug"() OWNER TO "postgres";

